    # Implementation of the shortest path finding algorithm (I'll use the implementation of Dijkstra's here)
    from heapq import heappush, heappop
    from collections import deque

    def build_path(pre):
        path = []
        t = target
        while t:
            path.append(t)
            t = pre.get(t, None)
        return path[::-1]

    def dijkstra(graph, source, target):
        dist = {node: float('inf') for node in graph}
        dist[source] = 0
        visited = set()
        priority_queue = [(0, source)]

        while priority_queue:
            current_dist, current_node = heappop(priority_queue)
            if current_node in visited:
                continue
            visited.add(current_node)

            for neighbor, weight in graph[current_node]:
                if current_dist + weight < dist[neighbor]:
                    dist[neighbor] = current_dist + weight
                    pre[neighbor] = current_node
                    heappush(priority_queue, (dist[neighbor], neighbor))

            if current_node == target:
                # We found the target node, now construct the path
                return dist[target], build_path(pre)

        # If we exit the loop, it means the target node is unreachable
        return float('inf'), []

    pre = {}
    distance, path = dijkstra(graph, source, target)
    return (distance, path)
