def astar(graph, start, goal):
    """A* search algorithm"""
    frontier = [(0, start, [])]
    came_from = {}
    cost_so_far = defaultdict(lambda: inf)

    while frontier:
        (cost, current, path) = heapq.heappop(frontier)

        if current == goal:
            return (cost, path + [current])

        if cost > cost_so_far[current]:
            continue

        for next_node, weight in graph.get(current, []):
            new_cost = cost + weight
            if new_cost < cost_so_far[next_node]:
                came_from[next_node] = current
                cost_so_far[next_node] = new_cost
                heapq.heappush(frontier, (new_cost, next_node, path + [current]))

    return (inf, None)

